import json, os
BASE="/home/hatch/workspace/divination/benchmark/phase3/runs/round84/predictions"
os.makedirs(BASE, exist_ok=True)
def W(cid, pred, basis, conf, trig):
    obj={"case_id":cid,"prediction_text":pred,"basis":basis,"confidence":conf,"trigger":trig}
    p=os.path.join(BASE,cid+".json")
    with open(p,"w",encoding="utf-8") as f: json.dump(obj,f,ensure_ascii=False,indent=1)
    with open(p,encoding="utf-8") as f: d=json.load(f)
    assert d["case_id"]==cid and set(d)=={"case_id","prediction_text","basis","confidence","trigger"}
    assert 0<=d["confidence"]<=1 and set(d["trigger"])=={"changed_main","reserve_used","disputed","reason"}
    print("ok",cid)
F=lambda: {"changed_main":False,"reserve_used":False,"disputed":False,"reason":""}
